// RAII: unique_ptr for dynamic arrays (Automatic delete[])
size_t array_size = 100;

void manages_resource_scope() {
    // Acquire resource (Allocation)
    auto data_array = std::make_unique<int[]>(array_size);

    // Use resource
    data_array[0] = 42;
    data_array[array_size - 1] = 99;

    // Optional: Get underlying raw pointer
    int* raw_ptr = data_array.get();

    // Reset: Deletes current array and becomes null
    // data_array.reset();

} // unique_ptr destructor calls delete[] on exit.
